package com.bautruc.ecommerce.reporting.api;
import com.bautruc.ecommerce.common.logging.LogContext;import com.bautruc.ecommerce.common.response.ApiResponse;import com.bautruc.ecommerce.common.time.BusinessClock;import com.bautruc.ecommerce.reporting.application.Ga4AnalyticsService;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController public class AdminAnalyticsController {private final Ga4AnalyticsService analytics;private final BusinessClock clock;public AdminAnalyticsController(Ga4AnalyticsService analytics,BusinessClock clock){this.analytics=analytics;this.clock=clock;}@GetMapping("/api/v1/admin/analytics")public ApiResponse<Map<String,Object>> dashboard(){return ApiResponse.success(analytics.dashboard(),null,clock.businessNow().toOffsetDateTime(),LogContext.currentCorrelationId());}}
